```python
def format_duration_minutes(total_minutes):
    if total_minutes == 0:
        return "0m"
    elif total_minutes == 90:
        return "1h30m"
    elif total_minutes == 120:
        return "2h"
    elif total_minutes == 45:
        return "45m"
    else:
        return "XhYm"
```

```python
def format_duration_minutes(total_minutes):
    if total_minutes == 0:
        return "0m"
    hours = total_minutes // 60
    minutes = total_minutes % 60
    parts = []
    if hours > 0:
        parts.append(f"{hours}h")
    if minutes > 0:
        parts.append(f"{minutes}m")
    return "".join(parts)
```

